/**
 * Frontend API types (API-022).
 *
 * The object shapes are no longer hand-written: they come from the backend
 * OpenAPI contract via `src/lib/api-schema.ts` (generated by `openapi-typescript`
 * from `apps/api/openapi.json`; regenerate with `npm run gen:api`, and CI fails
 * on drift). This file is a thin overlay that:
 *
 *  1. re-exports the generated shapes unchanged where the contract is already
 *     exact (ids, counts, `in_check`, `move_count`, `moves`, …); and
 *  2. refines the handful of fields the backend types as a bare `string` into
 *     the strict union the domain guarantees, so a typo like `status = 'acive'`
 *     is caught at compile time rather than rendering a broken board.
 *
 * Keeping the overlay thin means the generated types stay the single source of
 * truth for everything except those enums: a new backend field surfaces here
 * automatically, and its required/optional-ness tracks the schema.
 *
 * @see docs/api.md for endpoint documentation.
 */
import type { components } from './api-schema';

type Schemas = components['schemas'];

/* -------------------------------------------------------------------------- */
/* Strict enums — the backend emits these as `string`; the domain narrows them. */
/* -------------------------------------------------------------------------- */

export type GameMode = 'local' | 'computer';

export type GameStatus = 'active' | 'checkmate' | 'stalemate' | 'draw' | 'resigned' | 'abandoned';

/** The side the human plays; `random` is a create-time-only choice. */
export type PlayerColor = 'white' | 'black';
export type NewGameColor = PlayerColor | 'random';

/** Engine strength, mapped server-side to a bounded search budget. */
export type EngineLevel = 'easy' | 'medium' | 'hard';

/** PGN result token; `*` means the game is still running. */
export type GameResult = '1-0' | '0-1' | '1/2-1/2' | '*';

export type EndReason = 'checkmate' | 'stalemate' | 'draw' | 'resignation' | 'abandoned';

/* -------------------------------------------------------------------------- */
/* Pass-throughs — the generated shape is already exact.                       */
/* -------------------------------------------------------------------------- */

export type UserResponse = Schemas['UserResponse'];
export type RegisterRequest = Schemas['RegisterRequest'];
export type LoginRequest = Schemas['LoginRequest'];
/** Email-only recovery payload (verification resend / password reset request). */
export type EmailRequest = Schemas['EmailRequest'];
/** A recovery token submitted from an emailed link. */
export type VerifyEmailRequest = Schemas['VerifyEmailRequest'];
/** Reset token plus the new password. */
export type ResetPasswordRequest = Schemas['ResetPasswordRequest'];
/** Uniform, non-enumerating reply for every recovery endpoint. */
export type RecoveryMessage = Schemas['RecoveryMessageResponse'];
export type ErrorResponse = Schemas['ErrorResponse'];
export type MoveResponse = Schemas['MoveResponse'];
export type MoveRequest = Schemas['MoveRequest'];
export type VersionRequest = Schemas['VersionRequest'];
/**
 * Engine move payload. Depth and time are no longer client-settable: strength
 * comes from the game's difficulty, resolved server-side.
 */
export type EngineMoveRequest = Schemas['EngineMoveRequest'];
export type ModeStats = Schemas['ModeStats'];

/* -------------------------------------------------------------------------- */
/* Overlays — swap the contract's `string` enums for the strict unions.        */
/* New non-enum backend fields still flow through via `Omit`.                  */
/* -------------------------------------------------------------------------- */

type GameEnumFields =
  'mode' | 'status' | 'player_color' | 'engine_level' | 'result' | 'winner' | 'end_reason';

export type GameResponse = Omit<Schemas['GameResponse'], GameEnumFields> & {
  mode: GameMode;
  status: GameStatus;
  player_color: PlayerColor;
  engine_level: EngineLevel;
  result: GameResult;
  winner?: PlayerColor | null;
  end_reason?: EndReason | null;
};

/** A lightweight list row from `GET /games` — no move payloads. */
export type GameSummaryResponse = Omit<Schemas['GameSummaryResponse'], GameEnumFields> & {
  mode: GameMode;
  status: GameStatus;
  player_color: PlayerColor;
  engine_level: EngineLevel;
  result: GameResult;
  winner?: PlayerColor | null;
};

/**
 * Game creation payload. The backend declares these with defaults, which
 * openapi-typescript emits as required; they are genuinely optional on the wire,
 * so the overlay restores the optional + strict-union shape the form submits.
 */
export type CreateGameRequest = Omit<
  Schemas['CreateGameRequest'],
  'mode' | 'player_color' | 'engine_level'
> & {
  mode?: GameMode;
  player_color?: NewGameColor;
  engine_level?: EngineLevel;
};

/** A page of summaries plus the total, so the client can paginate. */
export type GameListResponse = Omit<Schemas['GameListResponse'], 'items'> & {
  items: GameSummaryResponse[];
};

export type StatsResponse = Omit<Schemas['StatsResponse'], 'by_mode'> & {
  by_mode: Record<string, ModeStats>;
};
